import runpy,json
from pathlib import Path
S=Path(__file__).resolve().parents[1];e=runpy.run_path(str(S/'work/write_superdaily_early.py'));add=e['add'];out=e['out'];cost=e['cost']
n={'策略方向':'條件成立固定多或空，不由當日開高低自動反轉方向。','進場相對開盤':'當根open−保存日開盤>=或<=X，皆可略過，含等號。','X點':'相對開盤的有號點數門檻。','進場相對MA':'啟用時需MA>0且當根open>=或<=均價，等號通過；不足樣本擋新進。','計算MA時間':'昨日1345用商品IsCloseTime前close；今早0500用IsSameDate日切前close；今早0845用日切後open，非嚴格固定鐘點。','X日MA':'依所選事件累積含最新樣本的算術均線，不夠時0。','價差條件':'保存日開盤−昨收現貨>=或<=價差點數；昨收現貨<=0時放行，非即時當根價差。','價差點數':'上述開盤對昨收現貨的有號固定點數。','停損比':'每次進場價加減%或點數，取樣open到固定損就按open退；移停存在也仍可查固定損。','啟動移停比':'每次進場價加減距離，取樣open達門檻後更新一般移停，不是時間延長門檻。','移停拉回比':'以目前open換距離，線只向有利方向更新，取樣open穿線退。','直接停利比':'每次入場價加減有利距離，取樣風控第一順位，無需先啟移。','KBAR間隔ex':'只篩持倉一般風控；日內時刻進出與延長判斷不需合相位。','開始交易時間':'一般風控ValidKBAR相位起點，不額外篩時刻新進。'}
me=[cost,'單一±1子項，只看open執行；一般風控優先序直停→已有移停→固定損→更新只向有利方向的線。時間退出在一般風控之前。','新倉不在同根再查風控。相鄰根合約不同按當根open平並continue，無平開續抱；末筆close平。']
ca=['進場用原始前根HHmm<目標<=本根，未對前根跨日正規化，行情缺段可漏進；退出把下根時間回退加2400，以跨越前根open成交。','MA命名時刻實際依商品收盤／交易日事件，不一定正好1345／0500／0845；資料缺失可改參考與進場。','Description的N日跌幅／持有數日文字不是核心，實際依所列開盤、MA、價差及時間分支。']
add('時間延長沖','依開盤漲跌門檻選較早或較晚的進場時刻，配開盤／MA／期現條件，持至設定出場或價格風控。','開盤擇時與時間交易',['保存昨收與日開盤，開盤−昨收>=開盤門檻用開高進場時間，否則用開低進場時間；未達門檻不代表一定負跳空。','空手且跨過所選時刻，當根open相對日開盤、保存開盤相對昨收現貨及MA全過，按策略方向進一口。'],['跨出場時間直接本根open平，不以獲利續留；若時刻設在下次日內，持倉可自然隔夜。一般持倉才受KBAR價格風控。']+me[1:2],me,ca,n|{'開盤門檻':'保存日開盤−昨收>=此點數用開高時刻；其餘用開低時刻，沒有另查是否真開低。','開高進場時間':'符合開盤>=門檻時唯一普通進場HHmm，跨越後取當根open，不需精確分鐘。','開低進場時間':'未達開盤門檻時用此進場HHmm，可含小幅開高日。','出場時間':'當根HHmm<=此值且下一根>，不論獲利直接當根open平；時間退出先於當根價格風控。'})
add('時間當沖_延長出場','可依開盤跳空提早進場，第一出場時刻達利潤距離就續抱，第二時刻強平，期間照常查價格風控。','時間交易與獲利續抱',['開盤−昨收落提早上下界且啟用時，改用提早進場時間，否則正常進場時間。跨所選時刻且開盤區間、相對開盤、MA、開盤期現差全過就open進一口。','昨收保存需前根位13:41至13:45後跨出此區，首根另初始化；開盤價只首根或精確08:45重設，夜盤不因此重設。'],['第一出場跨越時，多open>=入場+延長距離／空open<=入場−延長距離就保留，其餘當根open平；等號可留。這根直接return，不再一般價格風控。','第二出場時刻跨越便open強平，不再檢查利潤。其餘持倉依KBAR查原本的直停、移停、固定損與移停更新，延長不重設這些線。'],me,ca+['第一與第二時刻同根同時成立時第一分支先return，可越過第二次應平判斷；沒有獨立延長天數計數。'],n|{'進場時間':'未符合提早條件時普通進場HHmm；前根<此值<=本根才判，不是到時後持續等待。','出場時間':'第一時間跨越時只判延長獲利門檻，足利續抱、不足open平；優先於第二時刻及同根風控。','第二出場時間':'下一根跨過時不論利潤open平，但若同根第一時刻成立已return則本分支不執行。','提早進場':'開盤−昨收介於提早上下界時改用提早進場時間，其餘仍走正常時間。','提早進場時間':'提早條件成立時替代正常時刻，仍須所有新進濾網通過。','開盤小於可提早':'開盤−昨收的提早點數上界，含等號。','開盤大於可提早':'相同價差的提早點數下界，含等號。','開盤最高':'普通／提早進場皆要通過的開盤−昨收點數上界。','開盤最低':'相同價差下界，含等號，與提早上下界另算。','啟動延長持倉比':'入場價換%或點數成有利延長門檻；只於第一出場時間判，達到即保留，未另外建立新移停線。'})
(S/'analysis/SuperDaily.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n',encoding='utf8');print('Wrote Daily time extension pair')
